import type { GeoLocation } from "@/types/api";

// One selectable location: an Indonesian kabupaten or kota, or a whole country elsewhere, placed
// at a representative point inside it (lib/regions/place.ts says how each reads in text).
// Generated by scripts/regions/build_regions.py into catalog.json; never edit that file by hand.
export interface Region {
  id: string;
  // the place name alone; "(City)" or "(Regency)" only where a kabupaten and a kota share it
  name: string;
  official_name?: string;
  city: string;
  province?: string;
  admin_code?: string;
  country_code: string;
  country_name: string;
  latitude: number;
  longitude: number;
  timezone: string;
  continent: string;
}

export interface RegionCatalog {
  version: string;
  regions: Region[];
  // selectable entries plus hidden legacy ones, by id
  byId: Map<string, Region>;
  aliases: Record<string, string>;
}

let pending: Promise<RegionCatalog> | null = null;

// note: dynamic import keeps the ~190 KB catalogue out of every bundle but the two forms that
// pick a location. The promise is shared so both forms load it once.
export function loadRegionCatalog(): Promise<RegionCatalog> {
  pending ??= import("./catalog.json")
    .then((mod) => {
      const data = (mod.default ?? mod) as {
        version: string;
        regions: Region[];
        legacy: Region[];
        aliases: Record<string, string>;
      };
      const byId = new Map<string, Region>();
      for (const r of [...data.regions, ...data.legacy]) byId.set(r.id, r);
      return { version: data.version, regions: data.regions, byId, aliases: data.aliases };
    })
    .catch((error: unknown) => {
      pending = null; // a failed chunk load must be retryable
      throw error;
    });
  return pending;
}

// Resolves a retired id (ex; "id-jks") to the entry that replaced it.
export function resolveRegion(catalog: RegionCatalog, id: string | null | undefined): Region | undefined {
  if (!id) return undefined;
  return catalog.byId.get(catalog.aliases[id] ?? id);
}

export function toGeoLocation(
  region: Region,
  facility?: { facility_name?: string; facility_provider?: string }
): GeoLocation {
  const name = facility?.facility_name?.trim();
  const provider = facility?.facility_provider?.trim();
  return {
    region_id: region.id,
    region_name: region.name,
    country_code: region.country_code,
    country_name: region.country_name,
    city: region.city,
    latitude: region.latitude,
    longitude: region.longitude,
    timezone: region.timezone,
    continent: region.continent,
    ...(region.official_name && { official_name: region.official_name }),
    ...(region.province && { province: region.province }),
    ...(region.admin_code && { admin_code: region.admin_code }),
    ...(name && { facility_name: name }),
    ...(provider && { facility_provider: provider }),
  };
}
